PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE tools (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   category TEXT,   description TEXT,   location TEXT,   quantity INTEGER NOT NULL DEFAULT 1,   available_quantity INTEGER NOT NULL DEFAULT 1,   created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP , max_quantity_per_class INTEGER NULL, loan_duration_minutes INTEGER NULL, due_notice_enabled INTEGER NOT NULL DEFAULT 1, universal_return_enabled INTEGER NOT NULL DEFAULT 1, is_active INTEGER NOT NULL DEFAULT 1, max_quantity_per_chief INTEGER NULL, loan_duration_minutes_per_chief INTEGER NULL, display_order INTEGER, universal_return_enabled_for_chief INTEGER NOT NULL DEFAULT 1);
CREATE TABLE borrowers (   id INTEGER PRIMARY KEY AUTOINCREMENT,   class_name TEXT NOT NULL,   name TEXT NOT NULL,   created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE loans (   id INTEGER PRIMARY KEY AUTOINCREMENT,   borrower_id INTEGER NOT NULL,   tool_id INTEGER NOT NULL,   quantity INTEGER NOT NULL DEFAULT 1,   borrowed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,   returned_at DATETIME,   status TEXT NOT NULL DEFAULT 'borrowed', returned_by_id INTEGER REFERENCES borrowers(id), tool_item_id INTEGER REFERENCES tool_items(id), returned_quantity INTEGER NOT NULL DEFAULT 0, due_at DATETIME NULL, due_notice_sent_at DATETIME NULL, return_notice_sent_at DATETIME NULL, due_at_notification_sent_at DATETIME NULL,   FOREIGN KEY (borrower_id) REFERENCES borrowers(id),   FOREIGN KEY (tool_id) REFERENCES tools(id) );
CREATE TABLE tool_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tool_id INTEGER NOT NULL,
  management_number TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'available',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tool_id) REFERENCES tools(id)
);
CREATE TABLE loan_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  loan_id INTEGER NOT NULL,
  tool_item_id INTEGER NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, returned_at DATETIME, returned_by_id INTEGER
REFERENCES borrowers(id), overdue_minutes INTEGER NOT NULL DEFAULT 0, overdue_seconds INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (loan_id) REFERENCES loans(id),
  FOREIGN KEY (tool_item_id) REFERENCES tool_items(id),
  UNIQUE (loan_id, tool_item_id)
);
CREATE TABLE admin_users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  session_version INTEGER NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
, role TEXT NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE system_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  universal_return_time TEXT NULL,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE universal_return_times (id INTEGER PRIMARY KEY AUTOINCREMENT, return_time TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (return_time));
CREATE TABLE loan_return_notices (id INTEGER PRIMARY KEY AUTOINCREMENT, loan_id INTEGER NOT NULL, return_time_id INTEGER NOT NULL, notice_date TEXT NOT NULL, notified_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, overdue_notified_at DATETIME, return_time_type TEXT NOT NULL DEFAULT 'class', UNIQUE (loan_id, return_time_id, notice_date));
CREATE TABLE reservations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tool_id INTEGER NOT NULL,
  class_name TEXT NOT NULL,
  name TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  status TEXT NOT NULL DEFAULT 'waiting'
    CHECK (status IN ('waiting', 'completed', 'cancelled')),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tool_id) REFERENCES tools(id)
);
CREATE TABLE app_migrations (
  id TEXT PRIMARY KEY,
  applied_at DATETIME NOT NULL
);
CREATE TABLE notification_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  channel TEXT NOT NULL DEFAULT 'discord'
    CHECK (channel IN ('none', 'discord', 'line')),
  discord_webhook_encrypted TEXT NULL,
  line_channel_access_token_encrypted TEXT NULL,
  line_destination_type TEXT NULL
    CHECK (
      line_destination_type IS NULL
      OR line_destination_type IN ('user', 'group', 'room')
    ),
  line_destination_id TEXT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
, line_channel_secret_encrypted TEXT NULL);
CREATE TABLE line_notification_destinations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  destination_type TEXT NOT NULL
    CHECK (destination_type IN ('user', 'group', 'room')),
  destination_id TEXT NOT NULL UNIQUE,
  display_name TEXT NULL,
  last_seen_at DATETIME NOT NULL,
  created_at DATETIME NOT NULL,
  updated_at DATETIME NOT NULL
);
CREATE TABLE universal_return_times_chief (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  return_time TEXT NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (return_time)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_reservations_tool_status_created
  ON reservations(tool_id, status, created_at, id);
CREATE INDEX idx_line_notification_destinations_last_seen
  ON line_notification_destinations(last_seen_at DESC);
